    try { const m = JSON.parse(localStorage.getItem(this.META)||'null'); if(m) this.setState({name:m.name||this.state.name, fromName:m.fromName||'Acme', subject:m.subject??this.state.subject, preheader:m.preheader??this.state.preheader, versions:m.versions||[]}); } catch(e){}
