      const gj = window.grapesjs;
      if(!gj || !this.gjsRef.current || !document.getElementById('vb-blocks')){ if(++tries>100) return this.setState({loadNote:'Couldn’t load the editor — check your connection and reload'}); return void setTimeout(boot, 100); }
      this.initEditor(gj);
