    if(!c) return this.setState({sel:null});
    const type = c.get('type'), el = c.getEl();
    const txt = el ? (el.innerText||'').trim() : '';
    const leaf = c.components().filter(x=>x.get('type')!=='textnode').length===0;
    const tag = (c.get('tagName')||'').toLowerCase();
